function solve(s) {
    const countStack = [];
    const strStack = [];
    let cur = "";
    let num = 0;
    for (const c of s) {
        if (c >= "0" && c <= "9") {
            num = num * 10 + Number(c);
        } else if (c === "[") {
            countStack.push(num);
            strStack.push(cur);
            num = 0;
            cur = "";
        } else if (c === "]") {
            const times = countStack.pop();
            cur = strStack.pop() + cur.repeat(times);
        } else {
            cur += c;
        }
    }
    return cur;
}

