function solve(s) {
    let bestStart = 0, bestLen = 0;
    const n = s.length;
    for (let c = 0; c < n; c++) {
        for (let type = 0; type < 2; type++) {
            let l = c, r = c + type;
            while (l >= 0 && r < n && s[l] === s[r]) { l--; r++; }
            const len = r - l - 1;
            if (len > bestLen) { bestLen = len; bestStart = l + 1; }
        }
    }
    return s.slice(bestStart, bestStart + bestLen);
}

