function solve(s) {
    if (s.length === 0) return "";
    const rev = s.split("").reverse().join("");
    const t = s + "#" + rev;
    const fail = new Array(t.length).fill(0);
    for (let i = 1; i < t.length; i++) {
        let k = fail[i - 1];
        while (k > 0 && t[i] !== t[k]) k = fail[k - 1];
        if (t[i] === t[k]) k++;
        fail[i] = k;
    }
    const keep = fail[t.length - 1];
    return rev.slice(0, s.length - keep) + s;
}

